[{"order":1,"type":"heading","text":"Achieving UI Fluidity with Layout Animations in React Native"},{"order":2,"type":"paragraph","text":"Creating smooth, buttery animations is essential for modern mobile applications. When elements appear, disappear, or shift positions, abrupt changes degrade the user experience. In React Native, handling these layout shifts seamlessly requires leveraging LayoutAnimations and the LayoutAnimation API or Reanimated's layout transitions."},{"order":3,"type":"subheading","text":"Understanding LayoutAnimation vs LayoutTransitions"},{"order":4,"type":"paragraph","text":"React Native provides a built-in LayoutAnimation API that tells the native platform to animate all views on the next rendering cycle. This is fantastic for simple state changes. However, for complex, interruptible, and declarative animations, libraries like react-native-reanimated offer superior control via layout transitions."},{"order":5,"type":"subheading","text":"Step 1: Enabling Layout Animation on Android"},{"order":6,"type":"paragraph","text":"Before using LayoutAnimation in React Native for Android, you must explicitly enable it in your application's entry file or root component. iOS has this enabled by default."},{"order":7,"type":"code","text":"import { UIManager, Platform } from 'react-native';

if (Platform.OS === 'android') {
  if (UIManager.setLayoutAnimationEnabledExperimental) {
    UIManager.setLayoutAnimationEnabledExperimental(true);
  }
}"},{"order":8,"type":"subheading","text":"Step 2: Using the Built-in LayoutAnimation API"},{"order":9,"type":"paragraph","text":"To trigger an animation before modifying state, call LayoutAnimation.configureNext(). This configures the transition for the upcoming render pass."},{"order":10,"type":"code","text":"import React, { useState } from 'react';
import { View, Text, TouchableOpacity, LayoutAnimation, StyleSheet } from 'react-native';

export default function App() {
  const [expanded, setExpanded] = useState(false);

  const toggleExpand = () => {
    LayoutAnimation.configureNext(LayoutAnimation.Presets.easeInEaseOut);
    setExpanded(!expanded);
  };

  return (
    <View style={styles.container}>
      <TouchableOpacity onPress={toggleExpand} style={styles.button}>
        <Text style={styles.buttonText}>Toggle Box</Text>
      </TouchableOpacity>
      <View style={[styles.box, { height: expanded ? 200 : 50 }]} />
    </View>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1, justifyContent: 'center', alignItems: 'center' },
  button: { backgroundColor: '#007AFF', padding: 10, borderRadius: 5, marginBottom: 20 },
  buttonText: { color: '#fff', fontWeight: 'bold' },
  box: { width: 200, backgroundColor: '#FF3B30', borderRadius: 8 }
});"},{"order":11,"type":"subheading","text":"Step 3: Advanced Layout Transitions with Reanimated"},{"order":12,"type":"paragraph","text":"For declarative, component-level layout transitions that run on the UI thread, React Native Reanimated is the industry standard. It avoids the bridge for smooth 60+ FPS performance."},{"order":13,"type":"code","text":"import React, { useState } from 'react';
import { View, Text, TouchableOpacity, StyleSheet } from 'react-native';
import Animated, { FadeIn, FadeOut, Layout } from 'react-native-reanimated';

export default function ReanimatedList() {
  const [items, setItems] = useState([1, 2, 3]);

  const addItem = () => {
    setItems([...items, items.length + 1]);
  };

  const removeItem = (idToRemove) => {
    setItems(items.filter(id => id !== idToRemove));
  };

  return (
    <View style={styles.container}>
      <TouchableOpacity onPress={addItem} style={styles.button}>
        <Text style={styles.buttonText}>Add Item</Text>
      </TouchableOpacity>
      {items.map((item) => (
        <Animated.View
          key={item}
          entering={FadeIn}
          exiting={FadeOut}
          layout={Layout.springify()}
          style={styles.item}
        >
          <TouchableOpacity onPress={() => removeItem(item)}>
            <Text style={styles.itemText}>Item {item} (Tap to delete)</Text>
          </TouchableOpacity>
        </Animated.View>
      ))}
    </View>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1, padding: 40, marginTop: 50 },
  button: { backgroundColor: '#34C759', padding: 12, borderRadius: 8, alignItems: 'center', marginBottom: 20 },
  buttonText: { color: '#fff', fontWeight: 'bold' },
  item: { backgroundColor: '#E5E5EA', padding: 15, borderRadius: 8, marginBottom: 10 },
  itemText: { fontSize: 16 }
});"},{"order":14,"type":"subheading","text":"Best Practices for UI Fluidity"},{"order":15,"type":"bullet_point","text":"Always run heavy animations on the UI thread using Reanimated to prevent JS thread stutter."},{"order":16,"type":"bullet_point","text":"Use LayoutAnimation sparingly for simple UI toggles when adding external libraries is overkill."},{"order":17,"type":"bullet_point","text":"Combine entering, exiting, and layout animations carefully to avoid visual jarring during list mutations."},{"order":18,"type":"bullet_point","text":"Test animations on lower-end Android devices to ensure your spring configs and easing functions remain performant."}]
